```ts
// Suppose you already have the two declaration objects:
const parameterObject = /* your ParameterDeclaration */;
const variableDeclarationObject = /* your VariableDeclaration */;

// Convert them to JSON strings (or any string representation you prefer)
const leftString = JSON.stringify(parameterObject);
const rightString = JSON.stringify(variableDeclarationObject);

// Call the comparison function
const result = await functions.areDeclarationFlagsIdentical({
    left: leftString,
    right: rightString
});

console.log(result);   // true if flags match, false otherwise
